def product(prefix, title, keyword, description, categories, visible, use, structure, shape, palette, checks, sections, faq):
    return dict(prefix=prefix, slug='custom-'+prefix, title=title, keyword=keyword,
        seo_title=title.replace('Custom ', '')+' | VPN', seo_description=description,
        seo_category='christmas-packaging', categories=['christmas-packaging','gift-paper-boxes']+categories,
        tags=[keyword,'custom Christmas packaging','seasonal gift packaging'],
        feature=visible, industrial_use=use, paper_type='Material grade, thickness and surface to be selected from the packed-item brief and approved physical sample.',
        box_type=structure, shape=shape, liner_type='Custom insert and contact layers to be specified after measuring the actual contents.',
        color=palette, visual_reference=title+'; design reference, not a verified production sample.',
        content_file=prefix+'.html', caption_detail=visible+' Final material and finish require sample approval.',
        visible=visible, use=use, checks=checks, sections=sections, faq=faq)

